constraints:
1 <= Number of nodes <= 10^{5}
1 <= Data of a node <= 10^{5}

expected time complexity: O(Number of nodes).
expected auxiliary space: O(Height of the Tree).

standard_solution_code:
class Solution:

	def solve(self, l, r):
		if not l or not r:
			return None
		self.ans = (self.ans + l.data * r.data) % self.M
		self.solve(l.left, r.right)
		if l != r:
			self.solve(l.right, r.left)

	def imgMultiply(self, root):
		self.ans = 0
		self.M = int(1000000000.0 + 7)
		self.solve(root, root)
		return self.ans
